  VkApplicationInfo ai={VK_STRUCTURE_TYPE_APPLICATION_INFO,0,"g",0,"g",0,VK_API_VERSION_1_4};
  const char* ext[]={"VK_KHR_portability_enumeration"};
  VkInstanceCreateInfo ci={VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,0,0,&ai,0,0,0,0};
  VkInstance inst; if(vkCreateInstance(&ci,0,&inst)){puts("inst fail");return 1;}
  uint32_t n=1; VkPhysicalDevice pd; vkEnumeratePhysicalDevices(inst,&n,&pd);
